use hawdb::{ConcurrentDatabase, Database, KernelTelemetry, KernelTelemetryOperation, QueryOutput, QueryTelemetry, TelemetrySink, Value};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::Instant;

#[derive(Debug, Clone, Copy, Default)]
struct Events {
    wal_us: u64,
    wal_sync_us: u64,
    wal_bytes: u64,
    statement_us: u64,
    wal_events: usize,
    query_events: usize,
}
#[derive(Debug, Default)]
struct RecordingSink(Mutex<Events>);
impl RecordingSink {
    fn take(&self) -> Events { std::mem::take(&mut *self.0.lock().unwrap()) }
}
impl TelemetrySink for RecordingSink {
    fn record_query(&self, event: QueryTelemetry<'_>) {
        assert!(event.success);
        let mut sample = self.0.lock().unwrap();
        sample.statement_us += event.elapsed_micros;
        sample.query_events += 1;
    }
    fn record_kernel(&self, event: KernelTelemetry) {
        assert!(event.success);
        if event.operation == KernelTelemetryOperation::WalAppend {
            let mut sample = self.0.lock().unwrap();
            sample.wal_us += event.elapsed_micros;
            sample.wal_sync_us += event.fsync_micros;
            sample.wal_bytes += event.byte_count;
            sample.wal_events += 1;
        }
    }
}
enum Handle { Direct(Box<Database>), Concurrent(ConcurrentDatabase) }
impl Handle {
    fn write(&mut self, parameters: &[Value]) {
        match self {
            Self::Direct(db) => db.query_sql_with_params(INSERT, parameters).unwrap(),
            Self::Concurrent(db) => db.query_sql_with_params(INSERT, parameters).unwrap(),
        };
    }
    fn epoch(&self) -> u64 {
        match self { Self::Direct(db) => db.commit_epoch(), Self::Concurrent(db) => db.commit_epoch().unwrap() }
    }
}
fn main() {
    let root = PathBuf::from(format!("target/benchmarks/226-durability-breakdown-fixtures-{}", std::process::id()));
    std::fs::create_dir(&root).unwrap();
    let fixture = root.join("fixture");
    create_fixture(&fixture);
    let mut records = Vec::with_capacity(6 * WRITES);
    for (round, mode) in [(1, "direct"), (1, "concurrent"), (2, "concurrent"), (2, "direct"), (3, "direct"), (3, "concurrent")] {
        eprintln!("starting pair={round} mode={mode}");
        let path = root.join(format!("{round}-{mode}"));
        copy_fixture(&fixture, &path);
        let mut db = Database::open(&path).unwrap();
        assert_rows(&db.query_sql_with_params(POINT, &[Value::String(message_id(0, 0))]).unwrap(), 0, 0, 1);
        assert_rows(&db.query_sql_with_params(PAGE, &[Value::String(thread_id(0)), Value::Int(PAGE_ROWS as i64)]).unwrap(), 0, 0, PAGE_ROWS);
        let initial_epoch = db.commit_epoch();
        let sink = Arc::new(RecordingSink::default());
        db.set_telemetry_sink(Some(sink.clone()));
        let mut handle = if mode == "direct" { Handle::Direct(Box::new(db)) } else { Handle::Concurrent(db.into_concurrent()) };
        for request in 0..WRITES {
            let parameters = message_parameters(THREADS, request);
            let started = Instant::now();
            handle.write(&parameters);
            let total_us = started.elapsed().as_micros() as u64;
            let event = sink.take();
            assert_eq!(event.wal_events, 1);
            assert_eq!(event.query_events, 1);
            assert!(event.wal_sync_us <= event.wal_us);
            assert!(event.wal_us <= total_us + 1);
            assert!(event.statement_us <= total_us + 1);
            records.push((round, mode, request, total_us, event));
        }
        let epoch = handle.epoch();
        assert_eq!(epoch, initial_epoch + WRITES as u64);
        drop(handle);
        verify_recovery(&path, WRITES, epoch);
        eprintln!("completed pair={round} mode={mode}");
    }
    println!("pair,mode,request,total_us,wal_us,wal_sync_us,statement_us,wal_bytes,non_wal_sync_us,outside_statement_us");
    for (round, mode, request, total_us, event) in records {
        println!("{round},{mode},{request},{total_us},{},{},{},{},{},{}", event.wal_us, event.wal_sync_us, event.statement_us, event.wal_bytes, total_us.saturating_sub(event.wal_sync_us), total_us.saturating_sub(event.statement_us));
    }
    std::fs::remove_dir_all(root).unwrap();
}

const SMOKE: bool = cfg!(debug_assertions);
const THREADS: usize = if SMOKE { 4 } else { 128 };
const MESSAGES: usize = if SMOKE { 16 } else { 128 };
const CONTENT_BYTES: usize = 1024;
const PAGE_ROWS: usize = if SMOKE { 16 } else { 32 };
const WRITES: usize = if SMOKE { 8 } else { 512 };
const INSERT: &str = "INSERT INTO thread_messages \
    (content_message_id, thread_storage_id, order_index, content, token_count) \
    VALUES ($1, $2, $3, $4, $5)";
const POINT: &str =
    "SELECT content_message_id, thread_storage_id, order_index, content, token_count \
    FROM thread_messages WHERE content_message_id = $1";
const PAGE: &str =
    "SELECT content_message_id, thread_storage_id, order_index, content, token_count \
    FROM thread_messages WHERE thread_storage_id = $1 \
    ORDER BY order_index, content_message_id LIMIT $2";
const COMPLETE_THREAD: &str =
    "SELECT content_message_id, thread_storage_id, order_index, content, token_count \
    FROM thread_messages WHERE thread_storage_id = $1 \
    ORDER BY order_index, content_message_id";


fn create_fixture(path: &Path) {
    let mut db = Database::open(path).expect("fixture opens");
    db.query_sql(
        "CREATE TABLE thread_messages (content_message_id TEXT PRIMARY KEY, \
         thread_storage_id TEXT NOT NULL, order_index BIGINT NOT NULL, \
         content TEXT NOT NULL, token_count BIGINT NOT NULL)",
    )
    .unwrap();
    db.query_sql(
        "CREATE INDEX idx_thread_messages_order \
         ON thread_messages (thread_storage_id, order_index, content_message_id)",
    )
    .unwrap();
    for thread in 0..THREADS {
        let mut transaction = db.begin_transaction();
        for message in 0..MESSAGES {
            transaction
                .query_sql_with_params(INSERT, &message_parameters(thread, message))
                .unwrap();
        }
        transaction.commit().unwrap();
    }
    db.checkpoint().expect("fixture checkpoint succeeds");
}

fn verify_recovery(path: &Path, writes: usize, epoch: u64) {
    let mut db = Database::open(path).expect("complete WAL recovery succeeds");
    assert_eq!(db.commit_epoch(), epoch);
    for thread in 0..=THREADS {
        let count = if thread == THREADS { writes } else { MESSAGES };
        let output = db
            .query_sql_with_params(COMPLETE_THREAD, &[Value::String(thread_id(thread))])
            .unwrap();
        assert_rows(&output, thread, 0, count);
    }
    let total = db
        .query_sql("SELECT count(*) AS total FROM thread_messages")
        .unwrap();
    assert_eq!(
        total.rows[0].get("total"),
        Some(&Value::Int((THREADS * MESSAGES + writes) as i64))
    );
}

fn assert_rows(output: &QueryOutput, thread: usize, first: usize, count: usize) {
    assert_eq!(output.rows.len(), count);
    let expected_thread = Value::String(thread_id(thread));
    for (offset, row) in output.rows.iter().enumerate() {
        assert_eq!(
            row.get("content_message_id"),
            Some(&Value::String(message_id(thread, first + offset)))
        );
        assert!(matches!(row.get("content"), Some(Value::String(content))
            if content.len() == CONTENT_BYTES && content.bytes().all(|byte| byte == b'm')));
        assert_eq!(row.get("thread_storage_id"), Some(&expected_thread));
        assert_eq!(
            row.get("order_index"),
            Some(&Value::Int((first + offset) as i64))
        );
        assert_eq!(
            row.get("token_count"),
            Some(&Value::Int(CONTENT_BYTES as i64 / 4))
        );
    }
}

fn message_parameters(thread: usize, message: usize) -> Vec<Value> {
    vec![
        Value::String(message_id(thread, message)),
        Value::String(thread_id(thread)),
        Value::Int(message as i64),
        Value::String("m".repeat(CONTENT_BYTES)),
        Value::Int(CONTENT_BYTES as i64 / 4),
    ]
}

fn message_id(thread: usize, message: usize) -> String {
    format!("thread-{thread:04}:message-{message:04}")
}

fn thread_id(thread: usize) -> String {
    format!("thread-{thread:04}")
}

fn copy_fixture(source: &Path, destination: &Path) {
    std::fs::create_dir(destination).unwrap();
    for entry in std::fs::read_dir(source).unwrap() {
        let entry = entry.unwrap();
        let target: PathBuf = destination.join(entry.file_name());
        let kind = entry.file_type().unwrap();
        if kind.is_dir() {
            copy_fixture(&entry.path(), &target);
        } else {
            assert!(kind.is_file(), "fixture contains an unexpected symlink");
            std::fs::copy(entry.path(), target).unwrap();
        }
    }
}
